package com.aditi.smartpark.service;
import com.aditi.smartpark.dto.*;import com.aditi.smartpark.exception.*;import com.aditi.smartpark.model.*;import com.aditi.smartpark.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.*;import java.util.*;
@Service public class ParkingService {
 private final ParkingSlotRepository slots;private final VehicleBookingRepository bookings;
 public ParkingService(ParkingSlotRepository s,VehicleBookingRepository b){slots=s;bookings=b;}
 public List<ParkingSlot> availableSlots(){return slots.findByStatusOrderBySlotCodeAsc(SlotStatus.AVAILABLE);}
 @Transactional public BookingResponse book(BookingRequest r){String vehicle=r.vehicleNumber().toUpperCase(Locale.ROOT);if(bookings.findFirstByVehicleNumberAndExitTimeIsNull(vehicle).isPresent())throw new ConflictException("This vehicle already has an active booking");LocalDateTime entry=r.entryTime()==null?LocalDateTime.now():r.entryTime();if(entry.isAfter(LocalDateTime.now().plusMinutes(5)))throw new BadRequestException("Entry time cannot be in the future");ParkingSlot slot;if(r.slotId()!=null){slot=slots.findById(r.slotId()).orElseThrow(()->new ResourceNotFoundException("Parking slot not found: "+r.slotId()));if(slot.getStatus()!=SlotStatus.AVAILABLE)throw new ConflictException("Parking slot is already occupied");}else{List<ParkingSlot> a=slots.findAvailableForUpdate(SlotStatus.AVAILABLE);if(a.isEmpty())throw new ConflictException("No parking slots are currently available");slot=a.get(0);}slot.occupy();slots.save(slot);return BookingResponse.from(bookings.save(new VehicleBooking(vehicle,slot,entry)));}
 public List<BookingResponse> activeBookings(){return bookings.findByExitTimeIsNullOrderByEntryTimeAsc().stream().map(BookingResponse::from).toList();}
 public BookingResponse getBooking(Long id){return BookingResponse.from(bookings.findById(id).orElseThrow(()->new ResourceNotFoundException("Booking not found: "+id)));}
 public FareResponse fare(Long id,LocalDateTime at){VehicleBooking b=bookings.findById(id).orElseThrow(()->new ResourceNotFoundException("Booking not found: "+id));if(!b.isActive())throw new ConflictException("Fare estimate is only available for active bookings");LocalDateTime t=at==null?LocalDateTime.now():at;if(t.isBefore(b.getEntryTime()))throw new BadRequestException("Calculation time cannot be before entry time");return new FareResponse(id,b.getVehicleNumber(),b.getEntryTime(),t,Duration.between(b.getEntryTime(),t).toMinutes(),FeeCalculator.calculate(b.getEntryTime(),t));}
 @Transactional public CheckoutResponse checkout(Long id,LocalDateTime exit){VehicleBooking b=bookings.findById(id).orElseThrow(()->new ResourceNotFoundException("Booking not found: "+id));if(!b.isActive())throw new ConflictException("This booking has already been checked out");LocalDateTime t=exit==null?LocalDateTime.now():exit;if(t.isBefore(b.getEntryTime()))throw new BadRequestException("Exit time cannot be before entry time");BigDecimal fee=FeeCalculator.calculate(b.getEntryTime(),t);b.checkout(t,fee);b.getSlot().release();bookings.save(b);slots.save(b.getSlot());return new CheckoutResponse(id,b.getVehicleNumber(),b.getSlot().getSlotCode(),b.getEntryTime(),t,fee,b.getPaymentStatus().name(),"Checkout completed successfully");}
 public RevenueResponse revenue(LocalDate date){LocalDate d=date==null?LocalDate.now().toLocalDate():date;List<VehicleBooking> paid=bookings.findByPaymentStatusAndExitTimeBetween(PaymentStatus.PAID,d.atStartOfDay(),d.plusDays(1).atStartOfDay().minusNanos(1));BigDecimal total=paid.stream().map(VehicleBooking::getAmount).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);return new RevenueResponse(d,total.setScale(2),paid.size());}
}
